styles:
.b-tariffs {
    container-type: inline-size;
    --tariffs-gap: 1.5em;
}

.b-tariffs__title {
    margin: 0 0 1em;
}

/* A flex or grid box outranks the browser's own [hidden] rule. */
.b-tariffs__nav[hidden] {
    display: none;
}

/* The grid: up to `--tariffs-columns` across, fewer when a card would be narrower than 15em. */
.b-tariffs__track {
    display: grid;
    grid-template-columns: repeat(
        auto-fill,
        minmax(min(100%, max(15em, (100% - (var(--tariffs-columns, 3) - 1) * var(--tariffs-gap)) / var(--tariffs-columns, 3))), 1fr)
    );
    gap: var(--tariffs-gap);
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-tariffs__item {
    display: flex;
    min-width: 0;
}

/* One height across the row, and the button at the bottom of every card whatever is above it. */
.b-tariffs__card {
    display: flex;
    flex: 1 1 auto;
    flex-direction: column;
    gap: 0.75em;
    box-sizing: border-box;
    min-width: 0;
    margin: 0;
    padding: 1.75em 1.5em;
    border: 1px solid color-mix(in srgb, currentColor 15%, transparent);
    border-radius: 1em;
}

.b-tariffs__card.is-featured {
    border-color: currentColor;
    background: color-mix(in srgb, currentColor 5%, transparent);
}

.b-tariffs__flag {
    align-self: flex-start;
    margin: 0;
    padding: 0.25em 0.75em;
    border-radius: 999px;
    font-size: 0.8em;
    font-weight: 600;
    background: color-mix(in srgb, currentColor 12%, transparent);
}

.b-tariffs__badge {
    margin: 0;
    font-size: 0.8em;
    font-weight: 600;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    opacity: 0.7;
}

.b-tariffs__name {
    margin: 0;
    font-size: 1.35em;
}

.b-tariffs__price {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 0.25em;
    margin: 0;
}

.b-tariffs__amount {
    font-size: 2.25em;
    font-weight: 700;
    line-height: 1.1;
    font-variant-numeric: tabular-nums;
}

.b-tariffs__period {
    opacity: 0.7;
}

.b-tariffs__price--words {
    font-size: 1.5em;
    font-weight: 700;
}

.b-tariffs__includes {
    margin: 0.5em 0 0;
    font-weight: 600;
}

.b-tariffs__features {
    margin: 0;
    padding: 0;
    list-style: none;
}

.b-tariffs__features li {
    position: relative;
    margin: 0 0 0.4em;
    padding-inline-start: 1.5em;
    break-inside: avoid;
}

.b-tariffs__features li::before {
    content: '\2713';
    position: absolute;
    inset-inline-start: 0;
    font-weight: 700;
}

/* A long list in two columns, as in the sample the module was drawn from. */
.b-tariffs__features.is-wide {
    columns: 2;
    column-gap: 1.5em;
}

.b-tariffs__text {
    margin: 0;
    opacity: 0.8;
}

.b-tariffs__services {
    display: flex;
    flex-wrap: wrap;
    gap: 0.35em 0.75em;
    margin: 0;
    padding: 0;
    font-size: 0.9em;
    list-style: none;
}

.b-tariffs__services a {
    color: inherit;
}

.b-tariffs__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    margin-top: auto;
    padding: 0.8em 1.5em;
    border: 1px solid currentColor;
    border-radius: 999px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-align: center;
    text-decoration: none;
    text-transform: uppercase;
    color: inherit;
}

/* Neutral on purpose: the block knows neither the site's colours nor which of them is the
   background, so "primary" is the heavier of the looks and the site's copy paints it. */
.b-tariffs__button--primary {
    border-width: 2px;
    background: color-mix(in srgb, currentColor 12%, transparent);
}

.b-tariffs__button--link {
    border-color: transparent;
    padding-inline: 0;
    text-decoration: underline;
}

/* A slider is a ribbon that scrolls sideways — without the script, too. One card on a phone. */
.b-tariffs[data-tariffs-layout='slider'] .b-tariffs__viewport {
    overflow-x: auto;
    scrollbar-width: thin;
    scroll-snap-type: x mandatory;
}

.b-tariffs[data-tariffs-layout='slider'] .b-tariffs__track {
    display: flex;
}

.b-tariffs[data-tariffs-layout='slider'] .b-tariffs__item {
    flex: 0 0 calc((100% - (var(--tariffs-columns, 3) - 1) * var(--tariffs-gap)) / var(--tariffs-columns, 3));
    scroll-snap-align: start;
}

@container (max-width: 40em) {
    .b-tariffs[data-tariffs-layout='slider'] .b-tariffs__item {
        flex-basis: 100%;
    }
}

@container (max-width: 30em) {
    .b-tariffs__features.is-wide {
        columns: 1;
    }
}

.b-tariffs__nav {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 0.5em;
    margin-top: 1em;
}

.b-tariffs__count {
    margin: 0 auto 0 0;
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.08em;
}

.b-tariffs__arrow {
    width: 2.5em;
    height: 2.5em;
    font: inherit;
    color: inherit;
    background: none;
    border: 1px solid currentColor;
    border-radius: 50%;
    cursor: pointer;
}

.b-tariffs__arrow:disabled {
    opacity: 0.35;
    cursor: default;
}

script:
const layout = el.dataset.tariffsLayout || 'slider'
const viewport = el.querySelector('.b-tariffs__viewport')
const track = el.querySelector('.b-tariffs__track')
const nav = el.querySelector('.b-tariffs__nav')

if (layout === 'slider' && viewport && track && nav) {
  const still = window.matchMedia('(prefers-reduced-motion: reduce)')
  const items = Array.from(track.querySelectorAll('.b-tariffs__item'))
  const arrows = Array.from(nav.querySelectorAll('[data-tariffs-step]'))
  const current = nav.querySelector('[data-tariffs-current]')
  const total = nav.querySelector('[data-tariffs-total]')
  const two = (number) => String(number).padStart(2, '0')

  // One card further, measured rather than assumed: the number across changes with the width.
  const step = () => {
    const first = items[0]
    const gap = parseFloat(getComputedStyle(track).columnGap) || 0
    return first ? first.getBoundingClientRect().width + gap : viewport.clientWidth
  }
  const atEnd = () => viewport.scrollLeft + viewport.clientWidth >= viewport.scrollWidth - 2
  // The count is the first card in sight: "01 / 03" at the start, the last one that can lead at the end.
  const first = () => {
    const size = step()
    return size > 0 ? Math.min(items.length - 1, Math.round(viewport.scrollLeft / size)) : 0
  }

  const update = () => {
    // One card, or all of them in sight: nothing to turn, so neither arrows nor a count.
    nav.hidden = items.length < 2 || viewport.scrollWidth <= viewport.clientWidth + 1
    if (nav.hidden) return

    if (current) current.textContent = two(first() + 1)
    if (total) total.textContent = two(items.length)

    for (const arrow of arrows) {
      arrow.disabled =
        Number(arrow.dataset.tariffsStep) < 0 ? viewport.scrollLeft <= 1 : atEnd()
    }
  }

  for (const arrow of arrows) {
    arrow.addEventListener('click', () => {
      viewport.scrollBy({
        left: (Number(arrow.dataset.tariffsStep) || 1) * step(),
        behavior: still.matches ? 'auto' : 'smooth',
      })
    })
  }

  viewport.addEventListener('scroll', update, { passive: true })
  if ('ResizeObserver' in window) new ResizeObserver(update).observe(viewport)
  update()
}
